void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    double transformation[4][4];
    double vector[4];
    int i, j;

    /* Compute kernel */
    for (i = 0; i < 4; i++) {
        kernel[i] = exp(-index[i] * index[i] / (2 * r2 * r2)) * mul;
    }

    /* Apply prefilter iterations (blurring) */
    for (i = 0; i < prefilter; i++) {
        double blurred[4];
        for (j = 0; j < 4; j++) {
            double sum = 0.0;
            for (int k = 0; k < 4; k++) {
                sum += kernel[k] * kernel[(j + k) % 4];
            }
            blurred[j] = sum;
        }
        for (j = 0; j < 4; j++) {
            kernel[j] = blurred[j];
        }
    }

    /* Compute transformation matrix */
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            transformation[i][j] = kernel[(i + j) % 4];
        }
    }

    /* Compute vector based on frequency matrices */
    for (i = 0; i < 4; i++) {
        vector[i] = 1.0 / (1 + index[i] * index[i]);
    }

    /* Matrix-vector multiplication */
    for (i = 0; i < 4; i++) {
        double result = 0.0;
        for (j = 0; j < 4; j++) {
            result += transformation[i][j] * vector[j];
        }
        mu[i] = result;
    }

    /* Ensure non-negative results */
    for (i = 0; i < 4; i++) {
        if (mu[i] < 0.0) {
            mu[i] = 0.0;
        }
    }
}

void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    for (int i = 0; i < 4; i++) {
        kernel[i] = mul * exp(-index[i] * r2);
    }

    double freq_matrix[4][4];
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            freq_matrix[i][j] = (double)(i * j) / (index[i] + 1);
        }
    }

    for (int iter = 0; iter < prefilter; iter++) {
        double temp[4][4];
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                double sum = 0.0;
                for (int k = 0; k < 4; k++) {
                    sum += freq_matrix[i][k] * freq_matrix[k][j];
                }
                temp[i][j] = sum / 4.0;
            }
        }
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                freq_matrix[i][j] = temp[i][j];
            }
        }
    }

    double vector[4];
    for (int i = 0; i < 4; i++) {
        double sum = 0.0;
        for (int j = 0; j < 4; j++) {
            sum += freq_matrix[i][j];
        }
        vector[i] = sum;
    }

    for (int i = 0; i < 4; i++) {
        double result = 0.0;
        for (int j = 0; j < 4; j++) {
            result += kernel[j] * vector[j];
        }
        mu[i] = result;
        if (mu[i] < 0.0) {
            mu[i] = 0.0;
        }
    }
}

