    double freq_matrix[4][4] = {0};
    double transformed_matrix[4][4] = {0};
    double vector[4] = {0};

    // Compute kernel
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            kernel[i][j] = exp(-pow(i - j, 2) / (2 * r2 * r2)) * mul;
        }
    }

    // Apply filtering and blurring (simplified as identity operation for illustration)
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            freq_matrix[i][j] = kernel[i][j];
        }
    }

    // Apply transformation matrix (identity for illustration)
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            transformed_matrix[i][j] = freq_matrix[i][j];
        }
    }

    // Compute vector based on frequency matrices
    for (int i = 0; i < 4; ++i) {
        vector[i] = freq_matrix[index[i]][i];
    }

    // Compute matrix-vector multiplication
    for (int i = 0; i < 4; ++i) {
        mu[i] = 0.0;
        for (int j = 0; j < 4; ++j) {
            mu[i] += transformed_matrix[i][j] * vector[j];
        }
    }

    // Apply prefilter iterations (identity for this example)
    for (int k = 0; k < prefilter; ++k) {
        double mu_new[4];
        for (int i = 0; i < 4; ++i) {
            mu_new[i] = mu[i];
        }
        for (int i = 0; i < 4; ++i) {
            mu[i] = mu_new[i];
        }
    }

    // Ensure non-negative values
    for (int i = 0; i < 4; ++i) {
        if (mu[i] < 0.0) {
            mu[i] = 0.0;
        }
    }
}

void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    int i;
    double kernel[4][4] = { {0} };
    double freq[4][4] = { {0} };
    double freq_blur[4][4] = { {0} };
    double trans[4][4] = { {0} };
    double vec[4] = {0};
    double result[4] = {0};

    // Calculate kernel based on multiplier
    for (i = 0; i < 4; i++) {
        kernel[i][i] = exp(-0.5 * pow((i - 1.5) / r2, 2.0));
    }

    // Apply scaling factor
    for (i = 0; i < 4; i++) {
        kernel[i][i] *= mul;
    }

    // Apply prefilter iterations
    for (i = 0; i < prefilter; i++) {
        // Perform blurring operation
        int x, y;
        for (x = 0; x < 4; x++) {
            for (y = 0; y < 4; y++) {
                freq_blur[x][y] = (freq[x][y] + freq[(x + 1) % 4][y] + freq[(x - 1 + 4) % 4][y] + 
                                   freq[x][(y + 1) % 4] + freq[x][(y - 1 + 4) % 4]) / 5.0;
            }
        }

        // Update frequency matrix
        for (x = 0; x < 4; x++) {
            for (y = 0; y < 4; y++) {
                freq[x][y] = freq_blur[x][y];
            }
        }
    }

    // Calculate transformation matrix
    for (i = 0; i < 4; i++) {
        trans[i][i] = 1.0 / kernel[i][i];
    }

    // Calculate vector based on frequency matrix
    for (i = 0; i < 4; i++) {
        vec[i] = freq[index[i]][i];
    }

    // Perform matrix-vector multiplication
    for (i = 0; i < 4; i++) {
        int j;
        result[i] = 0.0;
        for (j = 0; j < 4; j++) {
            result[i] += trans[i][j] * vec[j];
        }
    }

    // Update mu array with results ensuring non-negative values
    for (i = 0; i < 4; i++) {
        mu[i] = (result[i] > 0.0) ? result[i] : 0.0;
    }
}

void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    double freq_matrices[4][4] = {0};
    double transformation_matrix[4][4] = {0};
    double vector[4] = {0};

    // Calculate kernel based on multiplier and r2
    for (int i = 0; i < 4; i++) {
        kernel[i] = mul * exp(-r2 * index[i] * index[i]);
    }

    // Apply filtering and blurring (simple Gaussian-like smoothing for this example)
    for (int i = 0; i < prefilter; i++) {
        for (int j = 0; j < 4; j++) {
            kernel[j] = (kernel[j] + kernel[(j + 1) % 4] + kernel[(j + 2) % 4] + kernel[(j + 3) % 4]) / 4.0;
        }
    }

    // Calculate frequency matrices and transformation matrix (simplified logic)
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            freq_matrices[i][j] = kernel[i] * kernel[j];
            transformation_matrix[i][j] = (i == j) ? 1.0 : 0.5;  // Identity matrix with adjustments
        }
    }

    // Calculate vector based on frequency matrices
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            vector[i] += freq_matrices[i][j] * kernel[j];
        }
    }

    // Multiply transformation matrix with vector and update mu
    for (int i = 0; i < 4; i++) {
        mu[i] = 0.0;
        for (int j = 0; j < 4; j++) {
            mu[i] += transformation_matrix[i][j] * vector[j];
        }
        // Ensure non-negative values
        mu[i] = (mu[i] < 0.0) ? 0.0 : mu[i];
    }
}
